package app.noir.mobile;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.util.UUID;
import static org.junit.Assert.*;

public final class ProfileStoreTest {
    Context isolated(){Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(app.getFilesDir(),"W4-test-"+UUID.randomUUID());root.mkdirs();return new ContextWrapper(app){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return root;}@Override public File getExternalFilesDir(String type){return new File(root,"external");}@Override public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences(root.getName()+name,mode);}};}
    @Test public void migrationKeepsDefaultInPlaceAndLinked()throws Exception{Context c=isolated();File original=new File(c.getFilesDir(),"library.json");String saved="{\"token\":\"old-peer\",\"pending\":[{\"id\":\"offline-op\"}],\"library\":{\"profileId\":\"pc-profile\",\"profileName\":\"Family\",\"instance\":\"legacy-instance\",\"items\":[]}}";try(FileOutputStream out=new FileOutputStream(original)){out.write(saved.getBytes(java.nio.charset.StandardCharsets.UTF_8));}ProfileStore p=new ProfileStore(c);assertEquals(ProfileStore.DEFAULT,p.current());assertEquals("pc-profile",p.get(p.current()).optString("pcProfileId"));new ProfileStore(c);assertEquals(saved,new String(java.nio.file.Files.readAllBytes(original.toPath()),java.nio.charset.StandardCharsets.UTF_8));DataStore data=new DataStore(c);assertEquals(1,data.pendingCount());assertEquals(c.getFilesDir(),data.context.getFilesDir());}
    @Test public void profileNamespacesAndPinsAreIndependent(){Context c=isolated();ProfileStore p=new ProfileStore(c);DataStore first=new DataStore(c);first.pref("language","ar");JSONObject second=p.create("Second","#7AA7FF");String id=second.optString("id");p.pin(id,"1234");assertFalse(p.checkPin(id,"wrong"));assertTrue(p.checkPin(id,"1234"));p.select(id,"1234");DataStore next=new DataStore(c);assertFalse(next.prefs().has("language"));next.pref("language","en");DataStore.flushWrites();assertNotEquals(first.context.getFilesDir(),next.context.getFilesDir());p.select(ProfileStore.DEFAULT,"");assertEquals("ar",new DataStore(c).prefs().optString("language"));assertEquals("en",new DataStore(c,id).prefs().optString("language"));assertThrows(IllegalArgumentException.class,()->p.delete(ProfileStore.DEFAULT));}
    @Test public void viewingEditsCopySharedItemsAndQueueExactOps(){Context c=isolated();DataStore data=new DataStore(c);JSONObject item=new JSONObject();DataStore.put(item,"id","viewing-item");DataStore.put(item,"group","group");data.rememberPhoneItem(item);String viewing=data.mark("viewing-item",true,0,false);JSONArray shared=data.itemsShared();JSONObject before=shared.optJSONObject(0);long original=DataStore.date(before.optJSONArray("viewings").optJSONObject(0).optString("watchedAt"));data.redateViewing("viewing-item",viewing,1_500_000_000_000L,true);assertEquals(original,DataStore.date(before.optJSONArray("viewings").optJSONObject(0).optString("watchedAt")));assertEquals(1,data.pendingCount("redate"));assertTrue(data.item("viewing-item").optJSONArray("viewings").optJSONObject(0).optBoolean("approximate"));data.deleteViewing("viewing-item",viewing);assertEquals(1,data.pendingCount("deleteViewing"));assertEquals(0,data.item("viewing-item").optJSONArray("viewings").length());DataStore.flushWrites();assertEquals(1,new DataStore(c).pendingCount("deleteViewing"));}
    // A fresh profile is unlinked: an empty link, never the text "null" sent to the PC as a profile id.
    @Test public void freshProfileHasNoPcLink(){Context c=isolated();ProfileStore p=new ProfileStore(c);assertEquals("",p.get(p.current()).optString("pcProfileId"));assertEquals("",new DataStore(c).linkedProfile());assertEquals("",p.create("Kids","#7AA7FF").optString("pcProfileId"));}
}
